# export channel-level aggregates for set compare
import zipfile, re, xml.etree.ElementTree as ET, io
from pathlib import Path
from collections import defaultdict
from decimal import Decimal
from datetime import datetime, timedelta

p=Path.home()/"Downloads"/"极乐引擎_明细数据_2026.11.02_1.xlsx"
z=zipfile.ZipFile(p)
ns={"m":"http://schemas.openxmlformats.org/spreadsheetml/2006/main"}
root=ET.fromstring(z.read("xl/sharedStrings.xml"))
ss=[]
for si in root.findall("m:si", ns):
    texts=[t.text or "" for t in si.findall(".//m:t", ns)]
    ss.append("".join(texts))

def col_to_idx(col):
    n=0
    for c in col:
        n=n*26+(ord(c)-64)
    return n-1

want_idx={}
wanted=["渠道码","产品ID","时间","新增-原始","新增-扣量","VIP充值-原始","VIP充值-扣量","金币充值"]
csv_new=defaultdict(Decimal)
csv_vip=defaultdict(Decimal)
csv_coin=defaultdict(Decimal)
csv_kou=defaultdict(Decimal)
by_day_new=defaultdict(Decimal)
by_day_rev=defaultdict(Decimal)

def cell_value(c):
    t=c.attrib.get("t")
    v=c.find("m:v", ns)
    if v is None or v.text is None:
        is_el=c.find("m:is", ns)
        if is_el is not None:
            return "".join(tt.text or "" for tt in is_el.findall(".//m:t", ns))
        return ""
    if t=="s": return ss[int(v.text)]
    return v.text

def num(x):
    x=str(x).strip().replace(",","")
    if not x: return Decimal(0)
    try: return Decimal(x)
    except: return Decimal(0)

def norm_date(t):
    t=str(t).strip()
    if t=="汇总": return None
    for fmt in ("%Y/%m/%d","%Y-%m-%d"):
        try: return datetime.strptime(t,fmt).date().isoformat()
        except: pass
    try:
        serial=float(t)
        d=(datetime(1899,12,30)+timedelta(days=serial)).date()
        return d.isoformat()
    except: return t

data=z.read("xl/worksheets/sheet1.xml")
cells_by_col={}
rows=0
for event, elem in ET.iterparse(io.BytesIO(data), events=("end",)):
    tag=elem.tag
    if tag.endswith("}c"):
        ref=elem.attrib.get("r","")
        m=re.match(r"([A-Z]+)", ref)
        if m:
            cells_by_col[col_to_idx(m.group(1))]=cell_value(elem)
        elem.clear()
    elif tag.endswith("}row"):
        rows+=1
        if rows==1:
            maxc=max(cells_by_col) if cells_by_col else -1
            headers=[cells_by_col.get(i,"") for i in range(maxc+1)]
            for i,h in enumerate(headers):
                if h in wanted: want_idx[h]=i
        else:
            def get(name):
                i=want_idx.get(name)
                return cells_by_col.get(i,"") if i is not None else ""
            t=norm_date(get("时间"))
            if t is None: 
                cells_by_col={}; elem.clear(); continue
            app=str(get("产品ID")).strip(); ch=str(get("渠道码")).strip()
            key=(app,ch)
            n=num(get("新增-原始")); vip=num(get("VIP充值-原始")); coin=num(get("金币充值")); kou=num(get("新增-扣量"))
            csv_new[key]+=n; csv_vip[key]+=vip; csv_coin[key]+=coin; csv_kou[key]+=kou
            by_day_new[t]+=n; by_day_rev[t]+=vip+coin
        cells_by_col={}
        elem.clear()

out=Path("/tmp/jile_xlsx_channels_20261102.tsv")
with out.open("w") as f:
    f.write("app_id\tchannel\tnew_raw\tnew_kou\tvip\tcoin\trev\n")
    for (app,ch) in sorted(csv_new):
        f.write(f"{app}\t{ch}\t{csv_new[(app,ch)]}\t{csv_kou[(app,ch)]}\t{csv_vip[(app,ch)]}\t{csv_coin[(app,ch)]}\t{csv_vip[(app,ch)]+csv_coin[(app,ch)]}\n")
print("channels", len(csv_new), "written", out)
print("totals new", sum(csv_new.values()), "rev", sum(csv_vip.values())+sum(csv_coin.values()), "kou", sum(csv_kou.values()))
print("by day new first/last:")
for d in sorted(by_day_new)[:3]:
    print(" ", d, by_day_new[d], by_day_rev[d])
print(" ...")
for d in sorted(by_day_new)[-3:]:
    print(" ", d, by_day_new[d], by_day_rev[d])
# cum to 10-25 for compare with old numbers
cum_n=sum(v for d,v in by_day_new.items() if d<='2026-10-25')
cum_r=sum(v for d,v in by_day_rev.items() if d<='2026-10-25')
print("cum to 10-25 new", cum_n, "rev", cum_r)
print("cum full new", sum(by_day_new.values()), "rev", sum(by_day_rev.values()))
