import zipfile, re, xml.etree.ElementTree as ET, io
from pathlib import Path
from collections import defaultdict
from decimal import Decimal
from datetime import datetime, timedelta

p=Path.home()/"Downloads"/"极乐引擎_明细数据_2026.11.02_1.xlsx"
z=zipfile.ZipFile(p)
ns={"m":"http://schemas.openxmlformats.org/spreadsheetml/2006/main"}
root=ET.fromstring(z.read("xl/sharedStrings.xml"))
ss=["".join(t.text or "" for t in si.findall(".//m:t", ns)) for si in root.findall("m:si", ns)]

def col_to_idx(col):
    n=0
    for c in col: n=n*26+(ord(c)-64)
    return n-1

def cell_value(c):
    t=c.attrib.get("t"); v=c.find("m:v", ns)
    if v is None or v.text is None: return ""
    return ss[int(v.text)] if t=="s" else v.text

def num(x):
    x=str(x).strip().replace(",","")
    return Decimal(x) if x else Decimal(0)

wanted=["产品ID","VIP充值-原始","VIP充值-扣量","金币充值","新增-原始"]
want_idx={}; cells={}; rows=0
by_app=defaultdict(lambda: defaultdict(Decimal))
total=defaultdict(Decimal)
for event, elem in ET.iterparse(io.BytesIO(z.read("xl/worksheets/sheet1.xml")), events=("end",)):
    if elem.tag.endswith("}c"):
        m=re.match(r"([A-Z]+)", elem.attrib.get("r",""))
        if m: cells[col_to_idx(m.group(1))]=cell_value(elem)
        elem.clear()
    elif elem.tag.endswith("}row"):
        rows+=1
        if rows==1:
            maxc=max(cells); headers=[cells.get(i,"") for i in range(maxc+1)]
            for i,h in enumerate(headers):
                if h in wanted: want_idx[h]=i
        else:
            def g(n):
                i=want_idx.get(n); return cells.get(i,"") if i is not None else ""
            app=str(g("产品ID")).strip()
            for k in ["VIP充值-原始","VIP充值-扣量","金币充值","新增-原始"]:
                v=num(g(k)); by_app[app][k]+=v; total[k]+=v
        cells={}; elem.clear()

print("TOTAL VIP原", total["VIP充值-原始"], "VIP扣", total["VIP充值-扣量"], "金币", total["金币充值"])
print("VIP原+金", total["VIP充值-原始"]+total["金币充值"], "VIP扣+金", total["VIP充值-扣量"]+total["金币充值"])
for app in ["YC-169","JHG-005","DX-084","SF-02","SF-146"]:
    d=by_app[app]
    print(app, "VIP原", d["VIP充值-原始"], "VIP扣", d["VIP充值-扣量"], "金币", d["金币充值"], "原+金", d["VIP充值-原始"]+d["金币充值"])
